def transform(grid):
    h, w = len(grid), len(grid[0])
    # Background is the dominant color; dividers are uniform rows/columns of a different color.
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]
    def bands(size, separators):
        result, start = [], 0
        for p in separators:
            if start < p: result.append((start, p))
            start = p + 1
        if start < size: result.append((start, size))
        return result
    rb, cb = bands(h, sep_rows), bands(w, sep_cols)
    tiles = []
    for ri, (r0, r1) in enumerate(rb):
        for ci, (c0, c1) in enumerate(cb):
            tile = [row[c0:c1] for row in grid[r0:r1]]
            score = sum(v != background for row in tile for v in row)
            tiles.append((score, ri, ci, tile))
    _, _, _, source = max(tiles, key=lambda t: t[0])
    out = [row[:] for row in grid]
    for _, ri, ci, _ in tiles:
        r0, r1 = rb[ri]; c0, c1 = cb[ci]
        for dr in range(r1-r0):
            for dc in range(c1-c0): out[r0+dr][c0+dc] = source[dr][dc]
    return out
